import z3

def solve_with_z3():
    num_golfers = 40
    num_groups = 10
    group_size = 4
    num_weeks = 5

    s = z3.Solver()

    # x[w][p][g] = True iff golfer p is in group g in week w
    x = [[[z3.Bool(f"x_{w}_{p}_{g}") for g in range(num_groups)] 
           for p in range(num_golfers)] 
           for w in range(num_weeks)]

    # 1. Each golfer in exactly one group per week
    for w in range(num_weeks):
        for p in range(num_golfers):
            s.add(z3.PbEq([(x[w][p][g], 1) for g in range(num_groups)], 1))

    # 2. Each group has exactly group_size golfers per week
    for w in range(num_weeks):
        for g in range(num_groups):
            s.add(z3.PbEq([(x[w][p][g], 1) for p in range(num_golfers)], group_size))

    # 3. No pair of golfers in same group more than once
    for w1 in range(num_weeks):
        for w2 in range(w1+1, num_weeks):
            for p1 in range(num_golfers):
                for p2 in range(p1+1, num_golfers):
                    for g in range(num_groups):
                        # Not both in same group in both weeks
                        s.add(z3.Or(z3.Not(x[w1][p1][g]), z3.Not(x[w1][p2][g]),
                                   z3.Not(x[w2][p1][g]), z3.Not(x[w2][p2][g])))

    print("Number of assertions:", len(s.assertions()))
    print("Solving...")
    start = time.time()
    result = s.check()
    elapsed = time.time() - start
    print(f"Result: {result}, time: {elapsed:.2f}s")

    if result == z3.sat:
        m = s.model()
        solution = []
        for w in range(num_weeks):
            for p in range(num_golfers):
                for g in range(num_groups):
                    if z3.is_true(m.eval(x[w][p][g])):
                        solution.append(g)
                        break
        return solution
    else:
        return None

sol = solve_with_z3()

