import z3, time

def solve_with_z3():
    num_golfers = 40
    num_groups = 10
    group_size = 4
    num_weeks = 5

    s = z3.Solver()

    # x[w][p][g] = True iff golfer p is in group g in week w
    x = [[[z3.Bool(f"x_{w}_{p}_{g}") for g in range(num_groups)] 
           for p in range(num_golfers)] 
           for w in range(num_weeks)]

    # 1. Each golfer in exactly one group per week
    for w in range(num_weeks):
        for p in range(num_golfers):
            s.add(z3.PbEq([(x[w][p][g], 1) for g in range(num_groups)], 1))

    # 2. Each group has exactly group_size golfers per week
    for w in range(num_weeks):
        for g in range(num_groups):
            s.add(z3.PbEq([(x[w][p][g], 1) for p in range(num_golfers)], group_size))

    # 3. No pair of golfers in same group more than once
    for p1 in range(num_golfers):
        for p2 in range(p1+1, num_golfers):
            together = []
            for w in range(num_weeks):
                for g in range(num_groups):
                    together.append((z3.And(x[w][p1][g], x[w][p2][g]), 1))
            s.add(z3.PbLe(together, 1))

    # Symmetry breaking: fix week 0 partition
    for g in range(num_groups):
        for i in range(group_size):
            p = g * group_size + i
            s.add(x[0][p][g])

    # Fix golfer 0 to group 0 in all weeks
    for w in range(num_weeks):
        s.add(x[w][0][0])

    print("Number of assertions:", len(s.assertions()))
    print("Solving...")
    start = time.time()
    result = s.check()
    elapsed = time.time() - start
    print(f"Result: {result}, time: {elapsed:.2f}s")

    if result == z3.sat:
        m = s.model()
        solution = []
        for w in range(num_weeks):
            for p in range(num_golfers):
                for g in range(num_groups):
                    if z3.is_true(m[x[w][p][g]]):
                        solution.append(g)
                        break
        return solution
    else:
        return None

def verify_solution(sol):
    num_golfers = 40
    num_groups = 10
    group_size = 4
    num_weeks = 5

    # Check each week has valid partition
    for w in range(num_weeks):
        week = sol[w*40:(w+1)*40]
        if len(week) != 40:
            return False, f"Week {w} has {len(week)} assignments"
        for g in range(num_groups):
            count = week.count(g)
            if count != group_size:
                return False, f"Week {w}, group {g} has {count} golfers"

    # Check no pair meets more than once
    pair_weeks = {}
    for w in range(num_weeks):
        week = sol[w*40:(w+1)*40]
        for g in range(num_groups):
            group_members = [p for p in range(40) if week[p] == g]
            for i in range(len(group_members)):
                for j in range(i+1, len(group_members)):
                    p1, p2 = group_members[i], group_members[j]
                    pair = (min(p1,p2), max(p1,p2))
                    if pair in pair_weeks:
                        return False, f"Pair {pair} meets in weeks {pair_weeks[pair]} and {w}"
                    pair_weeks[pair] = w

    total_pairs = len(pair_weeks)
    expected_pairs = num_weeks * num_groups * (group_size * (group_size - 1) // 2)
    if total_pairs != expected_pairs:
        return False, f"Total pairs {total_pairs} != expected {expected_pairs}"

    return True, f"Valid! All {total_pairs} pairs unique."

